+    const editor = createEditor({ container, initialValue: "> foo\nbar" });
+
+    editor.setSelection(0, 9);
+    toggleBlockquote(editor);
+
+    expect(editor.getDocument()).toBe("> foo\n> bar");
+    editor.destroy();
+  });
+
